from collections import deque
from typing import Callable, Hashable, Iterable, Optional, TypeVar
Q=TypeVar("Q", bound=Hashable)
def reachable(source: Q, target: Q, queries: Iterable[Q], approved: Callable[[Q,Q],bool]) -> bool:
    todo=deque([source]); seen={source}; universe=list(queries)
    while todo:
        u=todo.popleft()
        if u==target: return True
        for v in universe:
            if v not in seen and (approved(u,v) or approved(v,u)):
                seen.add(v); todo.append(v)
    return False

from typing import Sequence, Set, Tuple
def is_theory(matrix: Sequence[Sequence[bool]], primitive: Set[Tuple[int,int]]) -> bool:
    n=len(matrix)
    return (all(matrix[i][i] for i in range(n)) and all(not matrix[i][j] or matrix[j][i] for i in range(n) for j in range(n)) and all(not (matrix[i][j] and matrix[j][k]) or matrix[i][k] for i in range(n) for j in range(n) for k in range(n)) and all(matrix[i][j] for i,j in primitive))

from typing import List, Tuple
class DSU:
    def __init__(self,n:int): self.p=list(range(n)); self.rank=[0]*n
    def find(self,x:int)->int:
        while self.p[x]!=x: self.p[x]=self.p[self.p[x]]; x=self.p[x]
        return x
    def union(self,a:int,b:int)->None:
        a,b=self.find(a),self.find(b)
        if a==b:return
        if self.rank[a]<self.rank[b]:a,b=b,a
        self.p[b]=a
        if self.rank[a]==self.rank[b]:self.rank[a]+=1
def closure(n:int, edges:List[Tuple[int,int]])->DSU:
    d=DSU(n)
    for a,b in edges:d.union(a,b)
    return d

